# Let's find the smallest cube number that can be expressed as 
# the sum of two different positive cubes in two different ways

def find_smallest_taxicab_cube(limit=1000):
    # We'll use a dictionary to store sums of cubes
    sums = {}

    for a in range(1, limit):
        a3 = a**3
        for b in range(a+1, limit):
            b3 = b**3
            s = a3 + b3

            if s in sums:
                sums[s].append((a, b))
            else:
                sums[s] = [(a, b)]

    # Find sums that have at least 2 different representations
    candidates = []
    for s, pairs in sums.items():
        if len(pairs) >= 2:
            # Check that all pairs are different
            # (they should be by construction, but let's verify)
            candidates.append((s, pairs))

    if candidates:
        candidates.sort()
        return candidates[0]
    else:
        return None

result = find_smallest_taxicab_cube(200)
if result:
    print(f'Found: {result[0]} = {result[0]**(1/3):.0f}^3')
    print('Representations:')
    for a, b in result[1]:
        print(f'  {a}^3 + {b}^3 = {a**3} + {b**3} = {a**3 + b**3}')
else:
    print('Not found within limit')
