# Let's search for cube numbers that are sums of cubes in multiple ways
# We'll use a more efficient approach with hash map

def find_smallest_cube_taxicab(max_n=500):
    # Dictionary mapping sum -> list of (a,b) pairs
    sum_map = {}

    # Generate all sums a^3 + b^3 for 1 <= a < b <= max_n
    for a in range(1, max_n):
        a3 = a**3
        for b in range(a+1, max_n):
            s = a3 + b**3
            if s in sum_map:
                sum_map[s].append((a, b))
            else:
                sum_map[s] = [(a, b)]

    # Check which sums are perfect cubes and have >= 2 representations
    results = []
    for s, pairs in sum_map.items():
        if len(pairs) >= 2:
            # Check if s is a perfect cube
            cube_root = round(s ** (1/3))
            if cube_root**3 == s:
                results.append((s, cube_root, pairs))

    if results:
        results.sort()
        return results[0]
    return None

# Try with increasing limits
for limit in [200, 400, 600, 800]:
    result = find_smallest_cube_taxicab(limit)
