def find_smallest_taxicab(limit=2000):
    sums = {}

    for a in range(1, int(limit**(1/3)) + 10):
        a3 = a**3
        for b in range(a+1, int(limit**(1/3)) + 10):
            s = a3 + b**3
            if s > limit:
                break
            if s in sums:
                sums[s].append((a, b))
            else:
                sums[s] = [(a, b)]

    candidates = []
    for s, pairs in sums.items():
        if len(pairs) >= 2:
            candidates.append((s, pairs))

    if candidates:
        candidates.sort()
        return candidates[0]
    return None

result = find_smallest_taxicab(2000)
if result:
    s, pairs = result
    print(f'Smallest: {s}')
    print('Representations:')
    for a, b in pairs:
        print(f'  {a}^3 + {b}^3 = {a**3} + {b**3} = {s}')

    # Check if any smaller number exists
    print(f'\nChecking numbers < {s}:')
    for n in range(1, s):
        # Quick check - not exhaustive but good enough
        count = 0
        max_a = int(n**(1/3)) + 1
        for a in range(1, max_a):
            a3 = a**3
            remaining = n - a3
            if remaining <= 0:
                continue
            b = round(remaining ** (1/3))
            if b > a and b**3 == remaining:
                count += 1
        if count >= 2:
            print(f'Found smaller: {n}')
            break
else:
    print('Not found')
